SINA_SMART["anat1-heart"] = {"lecture":"anat1-heart","title":"Thorax part 5: the heart","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat1-heart:e0","text":"Heart in middle mediastinum, T4-T8, inside the pericardium.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-heart:e2","text":"Base = left atrium (posterior); right border: SVC, RA, IVC; left border: LV; inferior: RV.","topic":"Layers, surfaces, borders and sulci","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-heart:e3","text":"Coronary sulcus; anterior IV groove: LAD + great cardiac vein; posterior: PDA + middle cardiac vein.","topic":"Layers, surfaces, borders and sulci","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-heart:e1","text":"Layers: epicardium, myocardium, endocardium.","topic":"Pericardium","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-heart:e4","text":"Pericardium: fibrous + serous; transverse and oblique sinuses.","topic":"Pericardium","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-heart:e5","text":"RA: venae cavae, coronary sinus, pectinate muscles → tricuspid.","topic":"Chambers, valves and coronary circulation","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-heart:e6","text":"RV: trabeculae carneae, papillary muscles, chordae, moderator band → pulmonary valve.","topic":"Chambers, valves and coronary circulation","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-heart:e7","text":"LA: 4 pulmonary veins, touches oesophagus → mitral valve.","topic":"Chambers, valves and coronary circulation","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-heart:e8","text":"LV: thickest wall → aortic valve.","topic":"Chambers, valves and coronary circulation","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-heart:e9","text":"LCA → LAD + circumflex; RCA → SA/AV nodes, PDA.","topic":"Chambers, valves and coronary circulation","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"11ovpvc":"a","1driyot":"a","137cxrm":"a","1a58j8m":"a","1l1vou8":"a","14v9g6a":"a","11w3a5g":"a","1amtjo1":"a","1izrhgi":"a","1jtkae":"a","jkh015":"a","1oujn0z":"a","19dr55r":"a"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat1-heart:e0":{"s":0,"u":["Heart in middle mediastinum, T4-T8, inside the pericardium.","The heart lies in the middle mediastinum , inside the pericardium, between T4 and T8."],"dp":[]},"anat1-heart:e2":{"s":1,"u":["Base = left atrium (posterior); right border: SVC, RA, IVC; left border: LV; inferior: RV.","Borders: superior (auricles, ascending aorta, pulmonary trunk, SVC entry), inferior (right ventricle), left (left ventricle and left auricle), right (SVC, right atrium, IVC).","Sulci: sulcus terminalis (outside the right atrium; crista terminalis inside), coronary (AV) sulcus (right and left coronary, circumflex arteries, coronary sinus), anterior interventricular groove (LAD and great cardiac vein), posterior interventricular groove (posterior interventricular artery and middle cardiac vein)."],"dp":[{"h":"Why an inferior heart attack can slow the heart","t":"In most people the right coronary artery supplies the sinoatrial and atrioventricular nodes as well as the inferior wall of the left ventricle through the posterior descending artery. Blocking it can therefore cause both an inferior infarction and a slow rhythm or heart block, which doctors anticipate on the ECG. Source: the lecture's coronary circulation section."},{"h":"Note","t":"Borders : right = right atrium (+ SVC, IVC); left = left ventricle (+ left auricle); inferior = right ventricle . Base (posterior) = left atrium . Anterior surface = mostly right ventricle ."}]},"anat1-heart:e3":{"s":1,"u":["Coronary sulcus; anterior IV groove: LAD + great cardiac vein; posterior: PDA + middle cardiac vein.","Sulci: sulcus terminalis (outside the right atrium; crista terminalis inside), coronary (AV) sulcus (right and left coronary, circumflex arteries, coronary sinus), anterior interventricular groove (LAD and great cardiac vein), posterior interventricular groove (posterior interventricular artery and middle cardiac vein)."],"dp":[]},"anat1-heart:e1":{"s":2,"u":["Layers: epicardium, myocardium, endocardium.","Parietal pericardium = outer fibrous layer + inner serous layer; the visceral pericardium (epicardium) covers the heart; the pericardial space lies between the serous layers."],"dp":[]},"anat1-heart:e4":{"s":2,"u":["Pericardium: fibrous + serous; transverse and oblique sinuses.","Parietal pericardium = outer fibrous layer + inner serous layer; the visceral pericardium (epicardium) covers the heart; the pericardial space lies between the serous layers.","Sinuses: transverse (behind the ascending aorta and pulmonary trunk, in front of the left atrium and pulmonary veins) and oblique (behind the heart, bounded by the reflections around the pulmonary veins and IVC)."],"dp":[{"h":"Note","t":"Pericardium : fibrous + serous (parietal and visceral = epicardium). Transverse sinus lies behind the aorta and pulmonary trunk (surgeons pass a clamp through it); oblique sinus behind the LA."}]},"anat1-heart:e5":{"s":3,"u":["RA: venae cavae, coronary sinus, pectinate muscles → tricuspid.","Right atrium : receives SVC, IVC and the coronary sinus ; auricle with pectinate muscles ; smooth sinus venarum; outflow via the tricuspid valve ."],"dp":[]},"anat1-heart:e6":{"s":3,"u":["RV: trabeculae carneae, papillary muscles, chordae, moderator band → pulmonary valve.","Right ventricle : most of the anterior surface; trabeculae carneae , papillary muscles with chordae tendineae preventing cusp prolapse, and the moderator band (septomarginal trabecula); outflow through the pulmonary valve ."],"dp":[{"h":"Note","t":"Right ventricle : trabeculae carneae, papillary muscles + chordae, moderator band (carries the right bundle branch). Conduction : SA → AV → His → bundle branches → Purkinje."}]},"anat1-heart:e7":{"s":3,"u":["LA: 4 pulmonary veins, touches oesophagus → mitral valve.","Left atrium : most of the base, touches the oesophagus , receives four pulmonary veins ; outflow through the mitral (bicuspid) valve."],"dp":[{"h":"Clinical","t":"The left atrium touches the oesophagus : an enlarged LA (mitral stenosis) can cause dysphagia, and transoesophageal echo views it best."}]},"anat1-heart:e8":{"s":3,"u":["LV: thickest wall → aortic valve.","Left ventricle : long, conical, much thicker wall ; outflow through the aortic valve ."],"dp":[]},"anat1-heart:e9":{"s":3,"u":["LCA → LAD + circumflex; RCA → SA/AV nodes, PDA.","Conduction: SA node → AV node → bundle of His → bundle branches → Purkinje fibres."],"dp":[{"h":"Note","t":"Coronaries : LCA → LAD (anterior LV and septum, apex) + circumflex ; RCA → right heart, SA node (~60%) and AV node (~80%) , and usually the posterior descending artery (right dominance)."}]}},"meta":{"11ovpvc":{"a":"recall","vg":"anat1-heart:e2/recall/1"},"1driyot":{"a":"recall","vg":"anat1-heart:e2/recall/1"},"137cxrm":{"a":"recall","vg":"anat1-heart:e2/recall/2"},"1a58j8m":{"a":"recall","vg":"anat1-heart:e3/recall/1"},"1l1vou8":{"a":"recall","vg":"anat1-heart:e4/recall/1"},"14v9g6a":{"a":"recall","vg":"anat1-heart:e5/recall/1"},"11w3a5g":{"a":"recall","vg":"anat1-heart:e6/recall/1"},"1amtjo1":{"a":"recall","vg":"anat1-heart:e6/recall/2"},"1izrhgi":{"a":"recall","vg":"anat1-heart:e7/recall/1"},"1jtkae":{"a":"relationship","vg":"anat1-heart:e7/relationship/1"},"jkh015":{"a":"recall","vg":"anat1-heart:e9/recall/1"},"1oujn0z":{"a":"recall","vg":"anat1-heart:e3/recall/2"},"19dr55r":{"a":"recall","vg":"anat1-heart:e8/recall/1"}},"explRev":"58eddcc32886"};
